import {mountVariants} from './variants-ui.mjs';
import {templateVariants,validateVariantReply} from './variants-model.mjs';
import {Geometry} from './composition-model.mjs';
import {basePrompts,sceneStatus,appliedSceneStatus} from './engine.mjs';
import {SCENE_CATEGORIES,SCENE_MOTIONS,defaultSceneSettings,validateSceneSettings,sceneImage,templateScene,validateSceneDraft} from './scene-model.mjs';
import {sceneOptionLabels} from './scene-labels.mjs';
export function mountScenes({node,button,t,getState,persist,commit,renderShots,computed,copy,status}){
 let models=[],model='',cpu=true,busy=null,modelLoading=false,modelsLoaded=false;const widgets=new Map(),opened=new Set(),messages=new Map();
 try{const stored=JSON.parse(localStorage.getItem('artoftomworks.scene-dna.scene-ai'));model=typeof stored?.model==='string'?stored.model:'';cpu=stored?.cpu!==false;}catch{}
 let variants=null;
 const get=getState,store=()=>{try{localStorage.setItem('artoftomworks.scene-dna.scene-ai',JSON.stringify({model,cpu}));}catch{}};
 function snapshot(shot){const settings=validateSceneSettings(shot.sceneSettings||defaultSceneSettings()),image=sceneImage(get(),shot,settings);return {base:basePrompts(get(),shot).video,imageKey:Geometry.imageKey(image),settings,image};}
 function same(a,b){return a.base===b.base&&a.imageKey===b.imageKey&&JSON.stringify(a.settings)===JSON.stringify(b.settings);}
 function inform(id,text){messages.set(id,text);refresh();}
 function refresh(){for(const shot of get().shots){const w=widgets.get(shot.id);if(!w)continue;const draft=shot.sceneDraft,s=sceneStatus(get(),shot),working=busy?.shotId===shot.id&&busy.projectId===get().id;w.msg.textContent=messages.get(shot.id)||'';w.generate.disabled=!!busy;w.template.disabled=!!busy;w.cancel.hidden=!working;w.area.disabled=working;w.area.value=draft?.text||'';w.apply.disabled=working||!draft?.text.trim();w.restore.disabled=working||!(shot.sceneApplied?.applied||draft?.applied);w.copy.disabled=working||!draft?.text.trim()||s.stale;w.saveIdea.disabled=!!busy||!draft?.text.trim();w.state.textContent=working?t('sceneWorking'):draft?s.stale?t('sceneStale'):s.active?t('sceneApplied'):t('sceneUnapplied'):t('sceneUnapplied');w.origin.textContent=draft?.origin==='template'?t('sceneTemplateHint'):draft?.model||'';w.summary.textContent=draft?.summary||'';w.observations.textContent=draft?.observations||'';}variants?.refresh();}
 async function loadModels(id){if(modelLoading)return;if(location.protocol==='file:'){inform(id,t('sceneNoModels'));return;}modelLoading=true;try{const response=await fetch('/api/vision-models'),data=await response.json();if(!response.ok)throw Error(data.error);models=data.models;modelsLoaded=true;if(!models.includes(model))model=models[0]||'';store();for(const w of widgets.values()){w.model.replaceChildren(new Option(t('choose'),''));for(const name of models)w.model.append(new Option(name,name));w.model.value=model;}inform(id,models.length?models.length+' · Ollama':t('sceneNoModels'));}catch(e){inform(id,t('sceneNoModels')+' '+e.message);}finally{modelLoading=false;}}
 function saveDraft(shot,payload,origin,snap,usedModel=''){let draft;try{draft=validateSceneDraft({version:1,applied:false,origin,source:snap.settings.source,imageKey:snap.imageKey,text:payload.videoPrompt,summary:payload.summary,observations:payload.observations,base:snap.base,model:usedModel,settings:snap.settings});}catch{inform(shot.id,t('tooLong'));return;}shot.sceneDraft=draft;variants?.syncCurrent(shot);persist();computed();refresh();}
 async function generate(shot){if(busy){inform(shot.id,t('sceneBusy'));return;}const snap=snapshot(shot);if(!snap.image){inform(shot.id,t('sceneImageNeeded'));return;}if(location.protocol==='file:'||!model){inform(shot.id,t('sceneNoModels'));return;}if(!variants.room(shot,3))return;
  const projectId=get().id,usedModel=model,controller=new AbortController(),oldDraft=JSON.stringify(shot.sceneDraft),oldVariants=JSON.stringify(shot.sceneVariants);busy={projectId,shotId:shot.id,controller};messages.delete(shot.id);refresh();
  try{const response=await fetch('/api/scene',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({image:snap.image.data,base:snap.base,duration:shot.duration,settings:snap.settings,model:usedModel,cpu,variants:3})}),data=await response.json();if(!response.ok)throw Object.assign(Error(data.error||t('sceneError')),{code:data.code});const current=get().shots.find(s=>s.id===shot.id);if(get().id!==projectId||!current)return;if(!same(snap,snapshot(current))||JSON.stringify(current.sceneDraft)!==oldDraft||JSON.stringify(current.sceneVariants)!==oldVariants){messages.set(shot.id,t('sceneChanged'));return;}const batch=validateVariantReply(data);variants.appendBatch(current,batch,'vision',snap,usedModel);
  }catch(e){if(get().id===projectId)messages.set(shot.id,e.name==='AbortError'?t('sceneCancelled'):e.code==='RESOURCE_BUSY'?t('sceneResourceBusy'):t('sceneError')+' '+e.message);}finally{busy=null;refresh();}
 }
 function add(parent,shot){if(!shot.sceneApplied&&shot.sceneDraft?.applied)shot.sceneApplied=structuredClone(shot.sceneDraft);shot.sceneSettings??={...defaultSceneSettings(),source:!get().reference&&shot.result?'result':'reference'};const settings=shot.sceneSettings,details=node('details');details.className='scene-panel';details.open=opened.has(shot.id);details.ontoggle=()=>{if(details.open)opened.add(shot.id);else opened.delete(shot.id);};const summary=node('summary',t('scenePlanner'));let seen=false;try{seen=localStorage.getItem('artoftomworks.scene-dna.new.scene')==='seen';}catch{}if(!seen){const badge=button('NEW ×',()=>{try{localStorage.setItem('artoftomworks.scene-dna.new.scene','seen');}catch{}for(const n of document.querySelectorAll('.scene-new'))n.remove();},'badge scene-new');badge.setAttribute('aria-label',t('cropDismiss'));summary.append(' ',badge);}details.append(summary,node('p',t('sceneHelp')));const fields=node('div');fields.className='fields';const names=sceneOptionLabels(get().language);
  function select(key,title,values,captions){const l=node('label');l.append(node('span',title));const input=node('select');input.dataset.sceneSetting=key;for(let i=0;i<values.length;i++)input.append(new Option(captions[i],values[i]));input.value=settings[key];input.onchange=()=>{settings[key]=input.value;commit();refresh();};l.append(input);fields.append(l);return input;}
  select('category',t('sceneCategory'),SCENE_CATEGORIES,names.slice(0,8));select('motion',t('sceneMotion'),SCENE_MOTIONS,names.slice(8));select('source',t('cropSource'),['reference','result'],[t('cropReference'),t('cropResult')]);select('language',t('sceneLanguage'),['EN','HU','DE','FR','ES','IT','PT','PL'],['English','Magyar','Deutsch','Français','Español','Italiano','Português','Polski']);
  for(const [key,title,max]of [['mood','sceneMood',300],['customCategory','sceneCustom',500],['direction','sceneDirection',2000]]){const l=node('label');l.append(node('span',t(title)));const area=node(key==='mood'?'input':'textarea');area.value=settings[key];area.maxLength=max;area.dataset.sceneSetting=key;if(key!=='mood')area.rows=2;area.oninput=()=>{settings[key]=area.value;commit();refresh();};l.append(area);fields.append(l);}details.append(fields);
  const ai=node('details');ai.className='scene-ai-settings';ai.ontoggle=()=>{if(ai.open&&!modelsLoaded&&!modelLoading)void loadModels(shot.id);};ai.append(node('summary',t('sceneModel')));const modelLabel=node('label');modelLabel.append(node('span',t('sceneModel')));const picker=node('select');picker.dataset.sceneModel='';picker.append(new Option(t('choose'),''));for(const name of models)picker.append(new Option(name,name));if(model&&!models.includes(model))picker.append(new Option(model,model));picker.value=model;picker.onchange=()=>{model=picker.value;store();for(const w of widgets.values())w.model.value=model;};modelLabel.append(picker);const refreshButton=button(t('sceneRefresh'),async()=>{refreshButton.disabled=true;try{await loadModels(shot.id);}finally{refreshButton.disabled=false;}});refreshButton.dataset.sceneRefresh='';const cpuLabel=node('label');cpuLabel.className='lock';const cpuBox=node('input');cpuBox.type='checkbox';cpuBox.checked=cpu;cpuBox.onchange=()=>{cpu=cpuBox.checked;store();for(const w of widgets.values())w.cpu.checked=cpu;};cpuLabel.append(cpuBox,node('span',t('sceneCPU')));ai.append(modelLabel,refreshButton,cpuLabel,node('p',t('sceneModelHint')));details.append(ai,node('p',t('scenePrivacy')));
  const toolbar=node('div');toolbar.className='toolbar';const gen=button(t('variantsGenerate'),()=>void generate(shot),'primary'),template=button(t('variantsTemplate'),()=>{if(busy||!variants.room(shot,3))return;const snap=snapshot(shot);messages.delete(shot.id);variants.appendBatch(shot,templateVariants(snap.base,snap.settings,shot.duration),'template',snap,'');}),cancel=button(t('sceneCancel'),()=>busy?.controller.abort());gen.dataset.sceneGenerate='';template.dataset.sceneTemplate='';cancel.dataset.sceneCancel='';const resources=button(t('sceneResources'),async()=>{if(location.protocol==='file:'){inform(shot.id,t('sceneResourceUnknown'));return;}try{const r=await fetch('/api/resources'),data=await r.json();if(!r.ok)throw Error();inform(shot.id,`RAM: ${data.freeRAMMB} MB · VRAM: ${data.freeVRAMMB??'—'} MB · GPU: ${data.gpuUtilization??'—'}%`);}catch{inform(shot.id,t('sceneResourceUnknown'));}});toolbar.append(gen,template,cancel,resources);details.append(toolbar);variants.render(details,shot);
  const state=node('p'),msg=node('p');state.className='scene-state';msg.className='scene-message';msg.setAttribute('role','status');const origin=node('p');origin.className='muted';details.append(state,msg,origin);const label=node('label');label.append(node('span',t('sceneDraft')));const area=node('textarea');area.dataset.sceneDraft='';area.rows=12;area.maxLength=12000;area.oninput=()=>{if(!shot.sceneDraft){const snap=snapshot(shot);saveDraft(shot,{videoPrompt:area.value,summary:'',observations:''},'manual',snap);}else{shot.sceneDraft.text=area.value;shot.sceneDraft.applied=false;variants?.syncCurrent(shot);persist();computed();}refresh();};label.append(area);details.append(label);
  const actions=node('div');actions.className='toolbar';const apply=button(t('sceneApply'),()=>applyDraft(shot),'primary'),restore=button(t('sceneRestore'),()=>{if(shot.sceneDraft)shot.sceneDraft.applied=false;delete shot.sceneApplied;delete shot.sceneAppliedVariant;variants?.syncCurrent(shot);persist();computed();refresh();}),copyDraft=button(t('sceneCopy'),()=>{if(shot.sceneDraft?.text.trim()&&!sceneStatus(get(),shot).stale)void copy(shot.sceneDraft.text);});apply.dataset.sceneApply='';restore.dataset.sceneRestore='';copyDraft.dataset.sceneCopy='';const saveIdea=button(t('variantSave'),()=>variants.saveCurrent(shot));saveIdea.dataset.sceneSave='';actions.append(apply,copyDraft,saveIdea,restore);details.append(actions);
  const explanation=node('details');explanation.append(node('summary',t('sceneSummary')));const idea=node('p'),observations=node('p');explanation.append(idea,node('strong',t('sceneObservations')),observations);details.append(explanation);parent.append(details);widgets.set(shot.id,{msg,state,origin,area,summary:idea,observations,apply,restore,copy:copyDraft,saveIdea,generate:gen,template,cancel,model:picker,cpu:cpuBox});refresh();
 }
 function applyDraft(shot,reviewed=false){if(!shot.sceneDraft?.text.trim()){inform(shot.id,t('sceneEmpty'));return;}if(!reviewed&&sceneStatus(get(),shot).stale&&!confirm(t('sceneReview')))return;const snap=snapshot(shot);Object.assign(shot.sceneDraft,{base:snap.base,imageKey:snap.imageKey,source:snap.settings.source,settings:snap.settings,applied:true});shot.sceneApplied=structuredClone(shot.sceneDraft);if(shot.sceneActiveVariant)shot.sceneAppliedVariant=shot.sceneActiveVariant;else delete shot.sceneAppliedVariant;shot.promptLanguages??={image:'EN',video:'EN'};shot.promptLanguages.video='SOURCE';variants.syncCurrent(shot);messages.delete(shot.id);persist();computed();refresh();}
 function jump(){const first=document.querySelector('.scene-panel');if(!first){status('sceneFirst');return;}first.open=true;first.scrollIntoView({behavior:'smooth',block:'start'});}
 variants=mountVariants({node,button,t,getState:get,persist,computed,copy,download,snapshot,inform,refresh,apply:applyDraft,busy:()=>!!busy,editor:id=>widgets.get(id)?.area});
 window.addEventListener('pagehide',()=>busy?.controller.abort());return {add,refresh,jump,clearWidgets:()=>{widgets.clear();variants.clearWidgets();}};
}
